<?php $c = App\Models\Customer::find(1); $vs = \App\Models\Voucher::where("type", "Sales")->where("status", "Posted")->whereHasMorph("reference", [\App\Models\Invoice::class], function($q) { $q->whereHas("sale", function($q2) { $q2->where("customer_id", 1); }); })->get(); foreach($vs as $v) { $inv = $v->reference; if(!$inv) continue; foreach($inv->items as $it) { echo "InvItem qty: ".$it->quantity."\n"; } }
